<template>
<section class="canonical-desk continuity-page">
 <div class="page-heading"><h1>觀察與更新</h1><button class="primary" v-if="loaded" @click="newObservation">記錄觀察決定</button></div><p>保存目前繼續觀察、不採取行動或改變想法的原因。研究更新後，再對照原來的判斷。</p>
 <PrivateStateStatus :loading="loading" :loaded="loaded" :error="error" :message="message" :storage="storage" :auth-required="authRequired" reload-label="載入最新後重新核對" @reload="recheckDraft"/>
 <template v-if="loaded">
 <form @focusin="beginEdit" @input="beginEdit" v-if="form" @submit.prevent="submit" class="form-panel"><h2>{{ form.id?'修改觀察決定':'記錄觀察決定' }}</h2><div class="form-grid"><label>決定日期<input type="date" v-model="form.date" required/></label><label>目前決定<select v-model="form.action"><option value="watch">繼續觀察</option><option value="no_action">未採取行動</option><option value="reconsider">改變想法</option></select></label><label>當時報告版本<select v-model="form.report_id" @change="changeReport" :disabled="!!form.id"><option v-for="(r,id) in reportRegistry" :key="id" :value="id">{{ r.ticker }} · {{ r.revision }} · {{ r.created_at.slice(0,10) }}</option></select></label></div>
 <p class="muted">修改理由保留歷史；若改用另一份報告作新判斷，請另記一筆。所選版本不會隨最新版更換。</p><label>為什麼作這個決定<textarea v-model="form.reason" required maxlength="5000" rows="3"/></label><label>什麼證據會讓我改變看法<textarea v-model="form.invalidation" maxlength="5000" rows="3"/></label><fieldset><legend>這次最關心的研究主張（未選則追蹤整版）</legend><label v-for="c in reportRegistry[form.report_id]?.claims||[]" :key="c.id" class="checkbox-label"><input type="checkbox" :value="c.id" v-model="form.claim_ids"/>{{ c.text }}</label></fieldset><div class="button-row"><button class="primary" :disabled="busy">儲存觀察決定</button><button type="button" @click="form=null;resetBase()">取消</button></div></form>
 <label class="company-search">搜尋自己的決定<input type="search" v-model="query" @input="updateUrl()" placeholder="公司代號、理由或失效條件"/></label>
 <p v-if="!observations.length" class="empty-state">{{ research.observations.length?'沒有符合的觀察決定。':'尚無觀察決定。沒有買賣也可以保存當時判斷。' }}</p>
 <article v-for="r in observations" :key="r.id" class="decision-card" :id="'observation-'+r.id">
 <h2>{{ reportRegistry[r.report_id].ticker }} · {{ actionLabel(r.action) }} <span class="muted">{{ r.status==='archived'?'已歸檔':'' }}</span></h2><p>{{ r.date }} · {{ reportRegistry[r.report_id].revision }}</p><p><strong>當時理由：</strong>{{ r.reason }}</p><p><strong>改變看法的條件：</strong>{{ r.invalidation || '尚未記錄' }}</p><div class="button-row"><a :href="reportUrl(r.report_id)">閱讀當時研究</a><a v-if="latestId(r)!==r.report_id" :href="compareUrl(r.report_id)">和最新版比較</a><button @click="edit(r)">修改理由</button><button :disabled="busy" @click="toggle(r)">{{ r.status==='active'?'歸檔決定':'恢復決定' }}</button></div>
 <details :open="focused===r.id"><summary>{{ updateLabel(r) }}</summary><p v-if="latestId(r)===r.report_id">目前部署版本與當時版本相同，尚無新報告。</p><p v-else>當時 {{ reportRegistry[r.report_id].revision }} → 目前 {{ reportRegistry[latestId(r)].revision }}。下面列出文字與來源差異；判斷如何改變由你重新核對。</p><p v-if="changes(r)?.body_changed" class="muted">正文已改版。即使所選主張文字未變，仍可回讀原文；改版本身不代表原判斷被推翻。</p>
 <section v-for="c in changes(r)?.changes||[]" :key="c.id" class="claim-card"><h3>{{ changeLabel(c) }}</h3><p><strong>當時：</strong>{{ c.before?.text || '原版沒有這项主張' }}</p><p><strong>目前：</strong>{{ c.after?.text || '新版未保留這個主張ID' }}</p><details v-if="c.status==='changed'"><summary>條件與反證前後對照</summary><p>原反證：{{ c.before?.falsifier || '未提供' }}</p><ul><li v-for="text in c.before?.conditions||[]" :key="text">{{ text }}</li></ul><p>新反證：{{ c.after?.falsifier || '未提供' }}</p><ul><li v-for="text in c.after?.conditions||[]" :key="text">{{ text }}</li></ul></details><details v-if="c.sources_before.length||c.sources_after.length"><summary>兩版的具體來源與正文位置</summary><h4>當時版本</h4><SourceTrace :rows="c.sources_before"/><p v-if="!c.sources_before.length">當時版本未建立逐項來源定位，請回讀原版來源索引。</p><h4>目前版本</h4><SourceTrace :rows="c.sources_after"/></details></section>
 <button @click="startCheck(r)">記錄重新核對結果</button><article v-for="c in checksFor(r)" :key="c.id" class="review-entry"><strong>{{ c.date }} · {{ outcomeLabel(c.outcome) }} · {{ reportRegistry[c.report_id].revision }}</strong><p>{{ c.note }}</p><a :href="reportUrl(c.report_id)">閱讀這次核對的版本</a></article><p v-if="latestId(r)!==r.report_id&&!hasCurrentCheck(r)" class="muted">尚未保存對目前版本的重新核對。</p>
 </details>
 </article>
 <form @focusin="beginEdit" @input="beginEdit" v-if="checkForm" @submit.prevent="submitCheck" class="form-panel"><h2>重新核對 · {{ reportRegistry[checkForm.report_id]?.ticker }}</h2><div class="form-grid"><label>核對日期<input type="date" v-model="checkForm.date" required/></label><label>核對的研究版本<select v-model="checkForm.report_id"><option v-for="id in checkTargets" :key="id" :value="id">{{ reportRegistry[id].revision }}</option></select></label><label>證據與原判斷的關係<select v-model="checkForm.outcome"><option value="pending">尚待核對</option><option value="supported">支持原判斷</option><option value="weakened">削弱原判斷</option><option value="mixed">部分支持、部分削弱</option></select></label></div><label>哪些資料支持這個結果？下一步要看什麼？<textarea required v-model="checkForm.note" maxlength="5000" rows="4"/></label><div class="button-row"><button class="primary" :disabled="busy">儲存核對結果</button><button type="button" @click="checkForm=null;resetBase()">取消核對</button></div></form>
 <h2>交易引用的研究版本</h2><p v-if="!trades.length" class="empty-state">尚無符合的交易。交易記錄仍在買賣決策頁保存。</p><article v-for="r in trades" :key="r.id" class="decision-card"><h3>{{ r.date }} · {{ r.ticker }} · {{ r.side==='BUY'?'買入':'賣出' }}</h3><p>{{ r.reason }}</p><p v-if="!reportRegistry[r.report_id]" class="muted">{{ r.report_id?'引用版本未在本站登錄；原紀錄保持不變。':'當時未引用研究版本。' }}</p><div class="button-row"><a v-if="reportRegistry[r.report_id]" :href="reportUrl(r.report_id)">閱讀當時研究</a><a v-if="reportRegistry[r.report_id] && latestId(r)!==r.report_id" :href="compareUrl(r.report_id)">和最新版比較</a><a :href="'?workspace=review&record='+encodeURIComponent(r.id)">回顧這笔決策</a></div></article>
 <details><summary>私人記錄歷史與備份</summary><p>每次修改前的完整資料保留在歷史。這裡唯讀回查，完整JSON備份與還原在買賣決策頁。</p><a href="?workspace=ledger">開啟備份與還原</a><label>歷史私人資料<select @change="readHistory($event.target.value)"><option value="">選擇歷史版本</option><option v-for="h in history" :key="h.revision" :value="h.revision">版本{{ h.revision }} · {{ h.updated_at }}</option></select></label><div v-if="old"><h3>歷史版本{{ old.revision }} · 唯讀</h3><article v-for="r in old.state.research?.observations||[]" :key="r.id"><p>{{ r.date }} · {{ reportRegistry[r.report_id]?.ticker }} · {{ actionLabel(r.action) }}：{{ r.reason }}</p><a :href="reportUrl(r.report_id)">當時報告</a></article><p v-if="!old.state.research?.observations.length">這個歷史版本尚無觀察決定。</p><article v-for="c in old.state.research?.comparisons||[]" :key="c.id"><strong>{{ c.name }}</strong><p>{{ c.reports.map(r=>reportRegistry[r.report_id]?.ticker+' '+reportRegistry[r.report_id]?.revision).join(' ／ ') }}</p></article></div></details>
 </template>
</section>
</template>
<script setup>
import {computed,nextTick,onMounted,onUnmounted,ref,watch} from 'vue';
import {reportRegistry} from './report-registry.mjs';
import {emptyResearch,latestReport,reportChanges,reportPin} from './research-continuity.mjs';
import {usePrivateState} from './private-state.js';
import {loadLedgerVersion} from './ledger-store.js';
import PrivateStateStatus from './PrivateStateStatus.vue';
import SourceTrace from './SourceTrace.vue';
const {state,loaded,loading,busy,error,message,storage,authRequired,scope,history,load,save,beginEdit,resetBase,recheckDraft,context}=usePrivateState();
const form=ref(null),checkForm=ref(null),query=ref(''),focused=ref(''),old=ref(null);let historySequence=0;
watch(scope,(current,previous)=>{if(previous&&current!==previous){form.value=null;checkForm.value=null;query.value='';focused.value='';old.value=null;historySequence++;}});
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const research=computed(()=>state.value.research||emptyResearch());
const matches=text=>text.toLowerCase().includes(query.value.toLowerCase());
const observations=computed(()=>[...research.value.observations].reverse().filter(r=>matches(reportRegistry[r.report_id].ticker+' '+r.reason+' '+r.invalidation)));
const trades=computed(()=>[...state.value.records].filter(r=>r.status==='active'&&matches(r.ticker+' '+r.reason+' '+r.invalidation)).reverse());
const checkTargets=computed(()=>{const r=research.value.observations.find(r=>r.id===checkForm.value?.observation_id);return r?Object.keys(reportRegistry).filter(id=>reportRegistry[id].ticker===reportRegistry[r.report_id].ticker&&Date.parse(reportRegistry[id].as_of)>=Date.parse(reportRegistry[r.report_id].as_of)):[];});
const actionLabel=a=>({watch:'繼續觀察',no_action:'未採取行動',reconsider:'改變想法'}[a]);
const outcomeLabel=a=>({pending:'尚待核對',supported:'支持原判斷',weakened:'削弱原判斷',mixed:'結果混合'}[a]);
const reportUrl=id=>'?workspace=company&bundle='+encodeURIComponent(id)+'&researchTab=report';
const latestId=r=>latestReport(reportRegistry[r.report_id].ticker);
const compareUrl=id=>'?workspace=compare&compareReports='+encodeURIComponent(id+','+latestReport(reportRegistry[id].ticker))+'&questions=cash,capital,price';
const changes=r=>reportChanges(r.report_id,latestId(r),r.claim_ids);
const checksFor=r=>research.value.checks.filter(c=>c.observation_id===r.id).slice().reverse();
const hasCurrentCheck=r=>checksFor(r).some(c=>c.report_id===latestId(r));
const updateLabel=r=>latestId(r)===r.report_id?'目前版本與核對紀錄':hasCurrentCheck(r)?'新版差異與已保存的核對':'新版研究，待重新核對';
const changeLabel=c=>({changed:'主張或條件已變',removed:'新版未保留此主張',added:'新版新增主張',unchanged:c.evidence_changed?'主張文字相同，來源定位有變':'主張與已登錄來源相同'}[c.status]);
function updateUrl(push=false){const p=new URLSearchParams({workspace:'observations'});if(query.value)p.set('decisionSearch',query.value);if(focused.value)p.set('observation',focused.value);window.history[push?'pushState':'replaceState'](window.history.state,'','?'+p);}
function newObservation(){resetBase();beginEdit();const requested=new URLSearchParams(location.search).get('report'),report_id=reportPin(requested)?requested:latestReport('AMZN');form.value={id:'',date:today(),action:'watch',reason:'',invalidation:'',report_id,claim_ids:[]};checkForm.value=null;window.scrollTo({top:0,behavior:'instant'});}
function changeReport(){form.value.claim_ids=[];}
function edit(r){resetBase();beginEdit();form.value=JSON.parse(JSON.stringify(r));window.scrollTo({top:0,behavior:'instant'});}
async function submit(){const f=form.value,now=new Date().toISOString(),record={id:f.id||crypto.randomUUID(),date:f.date,action:f.action,reason:f.reason.trim(),invalidation:f.invalidation.trim(),...reportPin(f.report_id),claim_ids:[...f.claim_ids],status:f.status||'active',created_at:f.created_at||now,updated_at:now};const observations=research.value.observations.filter(r=>r.id!==record.id);if(await save({...state.value,research:{...research.value,observations:[...observations,record]}},'觀察決定與當時研究版本已保存。')){form.value=null;focused.value=record.id;updateUrl(true);}}
async function toggle(r){await save({...state.value,research:{...research.value,observations:research.value.observations.map(o=>o.id===r.id?{...o,status:r.status==='active'?'archived':'active',updated_at:new Date().toISOString()}:o)}},r.status==='active'?'決定已歸檔，原判斷仍可回查。':'決定已恢復。');}
async function startCheck(r){resetBase();beginEdit();checkForm.value={observation_id:r.id,date:today(),report_id:latestId(r),outcome:'pending',note:''};form.value=null;focused.value=r.id;updateUrl(true);await nextTick();document.querySelector('.form-panel')?.scrollIntoView({block:'start'});}
async function submitCheck(){const c={id:crypto.randomUUID(),observation_id:checkForm.value.observation_id,date:checkForm.value.date,...reportPin(checkForm.value.report_id),outcome:checkForm.value.outcome,note:checkForm.value.note.trim(),created_at:new Date().toISOString()};if(await save({...state.value,research:{...research.value,checks:[...research.value.checks,c]}},'重新核對已保存，原決定與原版報告保持不變。'))checkForm.value=null;}
async function readHistory(v){const sequence=++historySequence;old.value=null;if(!v)return;const expected=scope.value;try{const result=await loadLedgerVersion(v);if(sequence!==historySequence||expected!==scope.value||!loaded.value)return;if(result.owner_scope!==expected){old.value=null;await load();return;}old.value=result;}catch(e){error.value=e.message;}}
function pop(){const p=new URLSearchParams(location.search);if(p.get('workspace')!=='observations')return;query.value=p.get('decisionSearch')||'';focused.value=p.get('observation')||'';}
pop();if(new URLSearchParams(location.search).get('new')==='1')newObservation();onMounted(()=>window.addEventListener('popstate',pop));onUnmounted(()=>{historySequence++;window.removeEventListener('popstate',pop);});
</script>
